CREATE TABLE `property_seo` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`uuid` CHAR(36) NOT NULL,`property_id` BIGINT UNSIGNED NOT NULL,`title` VARCHAR(60) NULL,`description` VARCHAR(160) NULL,`keywords` JSON NULL,`canonical_url` VARCHAR(1000) NULL,`og_image_url` VARCHAR(1000) NULL,`robots` ENUM('INDEX_FOLLOW','NOINDEX_FOLLOW','INDEX_NOFOLLOW','NOINDEX_NOFOLLOW') NOT NULL DEFAULT 'INDEX_FOLLOW',`metadata_version` VARCHAR(20) NOT NULL DEFAULT '1.0',`schema_type` VARCHAR(80) NULL,`source` VARCHAR(120) NULL,`tags` JSON NULL,`custom_fields` JSON NULL,`created_by` CHAR(36) NULL,`updated_by` CHAR(36) NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),UNIQUE KEY `property_seo_uuid_key` (`uuid`),UNIQUE KEY `property_seo_property_id_key` (`property_id`),CONSTRAINT `property_seo_property_fk` FOREIGN KEY (`property_id`) REFERENCES `properties` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `property_seo_title_check` CHECK (`title` IS NULL OR CHAR_LENGTH(`title`) BETWEEN 1 AND 60),CONSTRAINT `property_seo_description_check` CHECK (`description` IS NULL OR CHAR_LENGTH(`description`) BETWEEN 1 AND 160)) ENGINE=InnoDB;
CREATE TABLE `property_media` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`uuid` CHAR(36) NOT NULL,`property_id` BIGINT UNSIGNED NOT NULL,`type` ENUM('IMAGE','VIDEO','FLOOR_PLAN','VIRTUAL_TOUR') NOT NULL,`category` ENUM('EXTERIOR','INTERIOR','BEDROOM','BATHROOM','KITCHEN','LIVING_ROOM','FLOOR_PLAN','LOCATION','AMENITIES','DOCUMENT','VIRTUAL_TOUR','OTHER') NOT NULL DEFAULT 'OTHER',`url` VARCHAR(2048) NOT NULL,`thumbnail_url` VARCHAR(2048) NULL,`mime_type` VARCHAR(120) NOT NULL,`extension` VARCHAR(10) NULL,`file_size_bytes` INT UNSIGNED NULL,`width_px` INT UNSIGNED NULL,`height_px` INT UNSIGNED NULL,`duration_ms` INT UNSIGNED NULL,`sort_order` INT NOT NULL DEFAULT 0,`is_cover` BOOLEAN NOT NULL DEFAULT FALSE,`metadata` JSON NULL,`provider` VARCHAR(80) NULL,`storage_key` VARCHAR(500) NULL,`created_by` CHAR(36) NULL,`updated_by` CHAR(36) NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),`deleted_at` DATETIME(3) NULL,PRIMARY KEY (`id`),UNIQUE KEY `property_media_uuid_key` (`uuid`),KEY `property_media_property_deleted_order_idx` (`property_id`,`deleted_at`,`sort_order`,`id`),KEY `property_media_property_type_deleted_idx` (`property_id`,`type`,`deleted_at`),KEY `property_media_cover_idx` (`property_id`,`is_cover`,`deleted_at`),CONSTRAINT `property_media_property_fk` FOREIGN KEY (`property_id`) REFERENCES `properties` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `property_media_order_nonnegative` CHECK (`sort_order` >= 0),CONSTRAINT `property_media_cover_type` CHECK (`is_cover` = FALSE OR `type` = 'IMAGE'),CONSTRAINT `property_media_video_duration` CHECK ((`type` = 'VIDEO' AND `duration_ms` IS NOT NULL AND `duration_ms` > 0) OR (`type` <> 'VIDEO' AND `duration_ms` IS NULL)),CONSTRAINT `property_media_dimensions` CHECK ((`width_px` IS NULL AND `height_px` IS NULL) OR (`width_px` IS NOT NULL AND `height_px` IS NOT NULL))) ENGINE=InnoDB;
